#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    // No argument provided
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    // Parse the argument as a decimal integer
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    // Invalid conversion or extra characters
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // Negative numbers are not allowed
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    // Zero rows – special case
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }

    // The original program only supports up to 60 rows (array size 61)
    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Generate Pascal's triangle using a single array
    unsigned long long row[61] = {0};
    for (int r = 0; r < n; ++r) {
        // First element of each row is 1
        row[0] = 1;
        // Compute inner elements from right to left
        for (int c = r; c > 0; --c) {
            row[c] = row[c] + row[c - 1];
        }
        // Print the current row
        for (int c = 0; c <= r; ++c) {
            if (c > 0) putchar(' ');
            printf("%llu", row[c]);
        }
        putchar('\n');
    }
    return 0;
}
